// Bump when the seed changes so browsers holding an older demo seed start fresh.
export const SEED_VERSION = 3;

const DAY = 864e5;

// Seeded event log: ledger counts + breakdowns. Inukjuak starts at 4 of 6.
export function seedEvents(uid, now = Date.now()) {
  const ev = [];
  EMBED.inv.forEach(([c, p, q, d]) =>
    ev.push({ id: uid(), type: "stock", community: c, part: p, delta: q, reason: "count", by: "Ledger count", ts: Date.parse(d + "T12:00:00") })
  );
  const b = (c, asset, part, daysAgo, fixedAfter) => {
    const id = uid();
    ev.push({ id, type: "breakdown", community: c, asset, part, ts: now - daysAgo * DAY, by: "Garage" });
    if (fixedAfter != null) ev.push({ id: uid(), type: "fixed", ref: id, community: c, ts: now - (daysAgo - fixedAfter) * DAY, by: "Garage" });
  };
  b("Inukjuak", "Water truck 2", "P03", 48, 6);
  b("Inukjuak", "Water truck 5", "P02", 40, 11);
  b("Inukjuak", "Intake pipe heater", "P09", 34, 19);
  b("Inukjuak", "Water truck 5", "P02", 9, null);
  b("Inukjuak", "Water truck 6", "P03", 3, null);
  b("Inukjuak", "Treatment plant UV unit", "P11", 5, null);
  b("Puvirnituq", "Water truck 3", "P01", 12, null);
  b("Salluit", "Sewage truck 4", "P06", 20, null);
  return ev;
}
